-- A quién va dirigido el descuento (TODOS por defecto, retrocompatible con lo que ya existe).
ALTER TABLE "descuentos" ADD COLUMN "publico_objetivo" VARCHAR(30) NOT NULL DEFAULT 'TODOS';

-- Lista de clientes elegibles cuando publico_objetivo = CLIENTES_ESPECIFICOS (uno o varios).
CREATE TABLE "descuentos_clientes" (
  "id_descuento_cliente" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY NOT NULL,
  "id_descuento" BIGINT NOT NULL,
  "id_cliente" INTEGER NOT NULL,
  UNIQUE ("id_descuento", "id_cliente")
);
ALTER TABLE "descuentos_clientes" ADD FOREIGN KEY ("id_descuento") REFERENCES "descuentos" ("id_descuento") ON DELETE CASCADE;
ALTER TABLE "descuentos_clientes" ADD FOREIGN KEY ("id_cliente") REFERENCES "clientes" ("id_cliente") ON DELETE CASCADE;

-- Registro de uso — solo para descuentos con código (cupón). La UNIQUE es lo que de verdad
-- impide que un mismo cliente use el mismo cupón dos veces, incluso ante compras simultáneas.
CREATE TABLE "descuentos_usos" (
  "id_uso" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY NOT NULL,
  "id_descuento" BIGINT NOT NULL,
  "id_cliente" INTEGER NOT NULL,
  "id_orden_compra" BIGINT,
  "fecha_uso" TIMESTAMP NOT NULL DEFAULT now(),
  UNIQUE ("id_descuento", "id_cliente")
);
ALTER TABLE "descuentos_usos" ADD FOREIGN KEY ("id_descuento") REFERENCES "descuentos" ("id_descuento") ON DELETE CASCADE;
ALTER TABLE "descuentos_usos" ADD FOREIGN KEY ("id_cliente") REFERENCES "clientes" ("id_cliente") ON DELETE CASCADE;
ALTER TABLE "descuentos_usos" ADD FOREIGN KEY ("id_orden_compra") REFERENCES "ordenes_compra" ("id_orden_compra") ON DELETE SET NULL;

-- Qué cupón (si alguno) se validó y quedó reservado para esta orden desde su creación —
-- así el uso se confirma en el mismo momento en que se acredita el saldo (orden aprobada).
ALTER TABLE "ordenes_compra" ADD COLUMN "id_descuento_cupon" BIGINT;
ALTER TABLE "ordenes_compra" ADD FOREIGN KEY ("id_descuento_cupon") REFERENCES "descuentos" ("id_descuento");
